98	function iconEntry(icon: Icon): Entry {
99	  return {
100	    id: `icon:${icon.id}`,
101	    kind: "icon",
102	    name: icon.name,
103	    keywords: icon.keywords,
104	    render: (opts) => ({
105	      format: "jsx",
